const KEY='hbTerminalProfileV2';
const n=v=>{const x=String(v??'').trim().replace(/^<|>$/g,'');const y=Number(x);return Number.isFinite(y)?y:null;};
const nums=s=>String(s||'').split(/[ ,;]+/).map(n).filter(x=>x!==null);
const pct=x=>Number.isFinite(x)?(x*100).toFixed(2)+'%':'invalid';
const topic=v=>TOPICS[String(v||'').toLowerCase().replace(/_/g,'-')]||ALIASES[String(v||'').toLowerCase()]||null;
const name=v=>String(v||'').toLowerCase().replace(/_/g,'-');
const getProfile=()=>{try{return JSON.parse(localStorage.getItem(KEY))||{xp:0,answered:0,correct:0,streak:0,badges:[]};}catch{return {xp:0,answered:0,correct:0,streak:0,badges:[]};}};
const saveProfile=p=>{try{localStorage.setItem(KEY,JSON.stringify(p));}catch{}};
const addXP=(p)=>{p.xp+=p.streak>0?2:1;p.level=1+Math.floor(p.xp/25);if(p.xp>=100&&!p.badges.includes('CENTURY'))p.badges.push('CENTURY');saveProfile(p);};
