 if(action==='new'){const title=args.slice(1).join(' ')||'Untitled case';db.push({id:'CASE-'+Date.now(),title,evidence:[],created:new Date().toISOString()});localStorage.setItem('hbCases',JSON.stringify(db));print('CASE CREATED · '+title,'ok');return;}
