function graph(type,args){
 const width=48,height=10;const pts=[];for(let i=0;i<width;i++){const t=i/(width-1)*Math.PI*2;let y=Math.sin(t);if(type==='square')y=y>=0?1:-1;if(type==='triangle')y=2*Math.abs(2*(i/(width-1))-1)-1;pts.push(Math.round((1-y)/2*(height-1)));}
 const rows=Array.from({length:height},()=>Array(width).fill(' '));pts.forEach((y,i)=>rows[y][i]='●');print('GRAPH · '+type.toUpperCase());rows.forEach(r=>print(r.join('')));
}
